package com.mfg.energy.controller;import com.mfg.common.api.*;import com.mfg.common.exception.BizException;import com.mfg.energy.entity.EquipmentUsage;import com.mfg.energy.repo.EquipmentUsageRepository;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;
@RestController @RequestMapping("/api/energy/usages") @RequiredArgsConstructor public class EquipmentUsageController{private final EquipmentUsageRepository repo;@PostMapping public ApiResponse<EquipmentUsage> create(@RequestBody EquipmentUsage u){if(u.getEnergyValue()==null||u.getEnergyValue().signum()<0)throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"能耗量必须为非负数");u.setStatDate(u.getStatDate()==null?LocalDate.now():u.getStatDate());if(u.getOutputQty()!=null&&u.getOutputQty().signum()>0)u.setUnitConsumption(u.getEnergyValue().divide(u.getOutputQty(),6,RoundingMode.HALF_UP));return ApiResponse.ok(repo.save(u));}@GetMapping public ApiResponse<java.util.List<EquipmentUsage>> list(){return ApiResponse.ok(repo.findAll());}}
